    private static RegistryObject<SharedMaterialItem> shared(String name, int oldMeta, TGSlotType slot, int size, BooleanSupplier enabled) {
        RegistryObject<SharedMaterialItem> item = ITEMS.register(name, () -> new SharedMaterialItem(oldMeta, slot, new Item.Properties().stacksTo(size)));
        SHARED_ITEMS.put(name, item);
        ENABLED.put(name, enabled);
        return item;
    }
    public static boolean enabled(String name) { return ENABLED.get(name).getAsBoolean(); }
